Given a string str containing lowercase alphabets, the task is to count the sub-strings that contain all the vowels at-least one time and there are no consonants (non-vowel characters) present in the sub-strings.Examples: Input: str = "aeoibsddaaeiouudb" Output: 4 Explanation: The 4 distinct substrings containing all the vowels in order are "aaeiouu", "aeiouu", "aeiou", and "aaeiou".Input: str = "aeoisbddiouuaedf" Output: 1Explanation: Only one substring "iouuae" contains all the vowels in order.Input: str = "aeouisddaaeeiouua" Output: 9 Explanation: There are 9 distinct substrings containing all vowels in order in the given string.Table of ContentGenerate all Substrings - O(n^2) Time and O(1) SpaceUsing Sliding Window - O(n) Time and O(1) SpaceGenerate all Substrings - O(n^2) Time and O(1) SpaceThe idea is to iterate over all possible substrings of the input string and check if each substring contains all the vowels ('a', 'e', 'i', 'o', 'u'). For each substring, a count is maintained for each vowel. If all vowels are found in a substring, it is considered valid, and the count is incremented. The process stops as soon as a consonant is encountered in a substring, as only vowel-only substrings are valid. Below is the implementation of the above approach:
            C++

    // C++ implementation to count substrings 
// that contains all vowels
#include <bits/stdc++.h>
using namespace std;

// Function to check if all vowels are present
bool containsAllVowels(vector<int>& vowelCount) {

    // Check if all vowels are found
    for (int i = 0; i < 5; i++) {
        if (vowelCount[i] == 0) return false;
    }
    return true;
}

// Function to count valid vowel-only substrings
int countVowelSubstrings(string& str) {
    int count = 0;
    int n = str.length();

    // Iterate over all possible starting points
    for (int i = 0; i < n; i++) {
        vector<int> vowelCount(5, 0);  
        int cnt = 0;

        // Iterate over possible ending points 
        // of substrings
        for (int j = i; j < n; j++) {
            char ch = str[j];

            // If consonant found, break the loop
            if (ch != 'a' && ch != 'e' && ch != 'i' 
                && ch != 'o' && ch != 'u') {
                break;
            }

            // Increment vowel count for the found vowel
            if (ch == 'a') vowelCount[0]++;
            else if (ch == 'e') vowelCount[1]++;
            else if (ch == 'i') vowelCount[2]++;
            else if (ch == 'o') vowelCount[3]++;
            else if (ch == 'u') vowelCount[4]++;

            // If all vowels are present, count 
            // the substring
            if (containsAllVowels(vowelCount)) {
                count++;
            }
        }
    }

    return count;
}

int main() {

    string str = "aeoibsddaaeiouudb";

    cout << countVowelSubstrings(str);

    return 0;
}


