                    break;
                }

                // Increment vowel count for the found vowel
                if (ch == 'a') vowelCount.set(0,
                    vowelCount.get(0) + 1);

                else if (ch == 'e') vowelCount.set(1,
                    vowelCount.get(1) + 1);

